"""NumPy-only specialization of verified librosa operations.

Derived from librosa0.10.2 onset_strength_multi,tempogram,feature.tempo and
power_to_db. Copyright 2013--2023 librosa development team. ISC license in
licenses/librosa-tempo/LICENSE.md. Active real-time BPM feature subset. Analysis22050Hz,
FFT1024/hop256,64 Slaney mel filters,terminal8s Hann autocorrelation,default
120BPM log prior and320BPM trial admission. These are not library limits.

The mel coefficients are generated by the original installed library and
hashed in validation. No copied/hand-tuned instrument/score/chord labels.
"""
from pathlib import Path
from collections import deque
import numpy as np
SR=22050;HOP=256;NFFT=1024

def envelope(y,mel):
    if len(y)<NFFT:return np.array([],np.float32)
    frames=np.lib.stride_tricks.sliding_window_view(y,NFFT)[::HOP]
    win=(.5-.5*np.cos(2*np.pi*np.arange(NFFT)/NFFT))
    fft=np.fft.rfft(frames*win,axis=-1).astype(np.complex64)
    power=np.abs(fft)**2
    # Avoid BLAS thread pools. This is the same matrix product.
    m=np.einsum('ij,kj->ik',mel,power,optimize=False)
    log=10*np.log10(np.maximum(np.float32(1e-10),m))
    return np.r_[np.float32(0),np.maximum(0,log[:,1:]-log[:,:-1]).mean(axis=0)]

def estimate(x):
    if len(x)<8 or np.max(x)<1e-6:return 0.
    n=len(x);window=.5-.5*np.cos(2*np.pi*np.arange(n)/n)
    # librosa.autocorrelate uses SciPy next_fast_len. A power-of-two padding
    # computes the same linear autocorrelation,with floating-roundoff only.
    fft=np.fft.rfft(x*window,n=1<<(2*n-1).bit_length())
    ac=np.fft.irfft(np.abs(fft)**2)[:n]
    maximum=np.max(np.abs(ac))
    if maximum>np.finfo(ac.dtype).tiny:ac=ac/maximum
    bpms=np.r_[np.inf,60.*SR/(HOP*np.arange(1,n))]
    with np.errstate(divide='ignore',invalid='ignore'):
        logprior=-.5*(np.log2(bpms)-np.log2(120.))**2
        max_idx=int(np.argmax(bpms<320));logprior[:max_idx]=-np.inf
        index=int(np.argmax(np.log1p(1e6*ac)+logprior))
    return float(bpms[index])

class StreamingFeatures:
    """Only complete causal FFT frames. PCM carry and observed feature history."""
    def __init__(self,mel,history_seconds=8.):
        self.mel=mel;self.carry=np.array([],np.float32);self.previous=None
        self.history=deque(maxlen=round(history_seconds*SR/HOP));self.frames=0
        self.win=.5-.5*np.cos(2*np.pi*np.arange(NFFT)/NFFT)
    def feed(self,samples):
        data=np.r_[self.carry,np.asarray(samples,dtype=np.float32)]
        if len(data)<NFFT:self.carry=data;return
        frames=np.lib.stride_tricks.sliding_window_view(data,NFFT)[::HOP]
        fft=np.fft.rfft(frames*self.win,axis=-1).astype(np.complex64)
        power=np.abs(fft)**2
        mel=np.einsum('ij,kj->ik',self.mel,power,optimize=False)
        log=10*np.log10(np.maximum(np.float32(1e-10),mel))
        prior=np.c_[self.previous,log[:,:-1]] if self.previous is not None else np.c_[log[:,0],log[:,:-1]]
        env=np.maximum(0,log-prior).mean(axis=0)
        self.history.extend(env.tolist());self.previous=log[:,-1].copy()
        self.frames+=len(frames);self.carry=data[len(frames)*HOP:].copy()
    def bpm(self):return estimate(np.array(self.history,dtype=np.float32))
